#!/usr/bin/env python3
"""Step 27: writes data/machines.json, the canonical 40-machine catalog (the single source; the
design table and the previews are generated from it). Rows: id, name, group, floor, slots, parts
(the icon's parts), motion, operation, contract {kind, ...params}, inputs, outputs, queue,
prereq {sign, packer, kettle, machines}, requires (systems that must exist), cost, growth,
upkeep_per_min, tiers, marginal, runtime (the model's type when implemented), step."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "..", "data", "machines.json")

def m(id, name, floor, parts, motion, operation, contract, inputs, outputs, queue, prereq, requires, cost, upkeep, tiers, marginal, slots=1, runtime=None, step=None):
    group = {"M": "manufacturing" if int(id[1:]) <= 8 else "advanced", "P": "packaging", "S": "storefront", "U": "support"}[id[0]]
    return {"id": id, "name": name, "group": group, "floor": floor, "slots": slots, "parts": parts, "motion": motion,
            "operation": operation, "contract": contract, "inputs": inputs, "outputs": outputs, "queue": queue,
            "prereq": prereq, "requires": requires, "cost": cost, "growth": 1.25, "upkeep_per_min": upkeep,
            "tiers": tiers, "marginal": marginal, "runtime": runtime,
            "step": step or {"M": 28 if int(id[1:]) <= 8 else 29, "P": 30, "S": 31, "U": 32}[id[0]]}

T3 = lambda a, b, c: [{"cost": 0, **a}, {"cost": 400, **b}, {"cost": 1000, **c}]
K, P, S, U = "kitchen", "packing", "shop", "support"
